#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    long long total = 0, last = 0, num = 0;
    char op = '+';
    for (size_t i = 0; i <= s.size(); i++) {
        char ch = i < s.size() ? s[i] : '+';
        if (ch >= '0' && ch <= '9') {
            num = num * 10 + (ch - '0');
        } else {
            if (op == '+') {
                total += last;
                last = num;
            } else if (op == '-') {
                total += last;
                last = -num;
            } else if (op == '*') {
                last *= num;
            } else {
                last /= num;
            }
            op = ch;
            num = 0;
        }
    }
    cout << total + last << "\n";

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();

        long total = 0, last = 0, num = 0;
        char op = '+';
        for (int i = 0; i <= s.length(); i++) {
            char ch = i < s.length() ? s.charAt(i) : '+';
            if (ch >= '0' && ch <= '9') {
                num = num * 10 + (ch - '0');
            } else {
                if (op == '+') {
                    total += last;
                    last = num;
                } else if (op == '-') {
                    total += last;
                    last = -num;
                } else if (op == '*') {
                    last *= num;
                } else {
                    last /= num;
                }
                op = ch;
                num = 0;
            }
        }
        System.out.println(total + last);
    }
}
